class CsvError(Exception):
    line: int
    col: int

    def __init__(self, message: str, line: int, col: int):
        self.line = line
        self.col = col
        super().__init__(f"{message} at line {line}, column {col}")


def parse(text: str, dialect: dict) -> list:
    delimiter = dialect.get("delimiter", ",")
    quote = dialect.get("quote", '"')
    escape = dialect.get("escape", None)
    skip_initial_space = dialect.get("skip_initial_space", False)
    comment = dialect.get("comment", None)
    skip_blank = dialect.get("skip_blank", True)
    strict = dialect.get("strict", True)
    header = dialect.get("header", False)
    fill = dialect.get("fill", None)
    null_values = dialect.get("null_values", [])
    infer_ints = dialect.get("infer_ints", False)
    trim = dialect.get("trim", False)

    if text.startswith("\ufeff"):
        text = text[1:]

    length = len(text)
    index = 0
    line = 1
    col = 1

    def advance():
        """Consume one character, counting CRLF as one physical break."""
        nonlocal index, line, col
        char = text[index]
        if char == "\r":
            line += 1
            col = 1
        elif char == "\n":
            if index == 0 or text[index - 1] != "\r":
                line += 1
            col = 1
        else:
            col += 1
        index += 1

    def consume_break():
        if text[index] == "\r":
            advance()
            if index < length and text[index] == "\n":
                advance()
        else:
            advance()

    def read_record():
        fields = []

        while True:
            if skip_initial_space:
                while index < length and text[index] == " ":
                    advance()

            quoted = (
                quote is not None
                and index < length
                and text[index] == quote
            )
            content = []

            if quoted:
                opening_line, opening_col = line, col
                advance()

                while True:
                    if index == length:
                        raise CsvError(
                            "Unterminated quoted field",
                            opening_line,
                            opening_col,
                        )

                    char = text[index]

                    if escape is not None and char == escape:
                        advance()
                        if index == length:
                            raise CsvError(
                                "Unterminated quoted field",
                                opening_line,
                                opening_col,
                            )
                        content.append(text[index])
                        advance()
                    elif char == quote:
                        if (
                            escape is None
                            and index + 1 < length
                            and text[index + 1] == quote
                        ):
                            content.append(quote)
                            advance()
                            advance()
                        else:
                            advance()
                            break
                    else:
                        content.append(char)
                        advance()

                if (
                    index < length
                    and text[index] != delimiter
                    and text[index] not in "\r\n"
                ):
                    if strict:
                        raise CsvError(
                            "Unexpected character after closing quote",
                            line,
                            col,
                        )

                    while (
                        index < length
                        and text[index] != delimiter
                        and text[index] not in "\r\n"
                    ):
                        content.append(text[index])
                        advance()
            else:
                while (
                    index < length
                    and text[index] != delimiter
                    and text[index] not in "\r\n"
                ):
                    content.append(text[index])
                    advance()

            fields.append(("".join(content), quoted))

            if index == length:
                return fields

            if text[index] == delimiter:
                advance()
                # Continue even at EOF: a final delimiter adds an empty field.
                continue

            consume_break()
            return fields

    def records():
        while index < length:
            if comment is not None and text[index] == comment:
                while index < length and text[index] not in "\r\n":
                    advance()
                if index < length:
                    consume_break()
                continue

            if skip_blank and text[index] in "\r\n":
                consume_break()
                continue

            yield read_record()

    def convert(value, quoted):
        if quoted:
            return value

        if trim:
            value = value.strip(" \t")

        if value in null_values:
            return None

        if infer_ints:
            digits = value[1:] if value.startswith("-") else value
            if digits and all("0" <= char <= "9" for char in digits):
                try:
                    return int(value)
                except ValueError:
                    # Support integers beyond Python's configurable limit
                    # on the number of digits in a string-to-int conversion.
                    number = 0
                    for start in range(0, len(digits), 9):
                        chunk = digits[start:start + 9]
                        number = number * (10 ** len(chunk)) + int(chunk)
                    return -number if value.startswith("-") else number

        return value

    result = []
    header_names = None

    for raw_record in records():
        if header and header_names is None:
            header_names = []
            occurrences = {}

            for position, (value, _) in enumerate(raw_record, 1):
                name = value if value else f"col{position}"
                count = occurrences.get(name, 0) + 1
                occurrences[name] = count
                header_names.append(
                    name if count == 1 else f"{name}_{count}"
                )
            continue

        values = [convert(value, quoted) for value, quoted in raw_record]

        if not header:
            result.append(values)
            continue

        record = {
            name: values[position] if position < len(values) else fill
            for position, name in enumerate(header_names)
        }

        if len(values) > len(header_names):
            record["_extra"] = values[len(header_names):]

        result.append(record)

    return result
